<script lang="ts">
import { readMapData, type FloodDetail } from './flood';
import type { DetailField } from './detailGroups';
let { id, fields, releaseId, onlocation }: { id: string; fields: DetailField[]; releaseId?: string; onlocation: (id: string, point: [number, number] | null) => void } = $props();
type Section<T> = { status: 'loading' } | { status: 'unavailable' } | { status: 'ready'; data: T };
type Facts = { location?: { coordinates: [number, number] } | null; parcel: { parcel_number: string | null; address: string | null; mapped_acres: string | null; updated_at: string }; source: string; owner_labels: null | { entity_name_indicator: string | null }; sales: unknown[] };
type Tax = { bills: unknown[]; foreclosure_cases: unknown[]; reported_delinquent_total: string | null; note: string };
type Vacancy = { available: boolean; tier: string; reason: string };
type Soil = { available: boolean; reason?: string; total_acres: number | null; uses: { use: string; rated: { rating: string; area: { acres: number } }[]; unrated: { acres: number }; uncovered: { acres: number }; ambiguous: { acres: number }; next_step: string }[]; freshness: { stale: boolean; reasons: string[]; refresh_failed_at: string | null } };
type Freshness = { stale: boolean; reasons: string[]; source_fetched_at: string | null; refresh_failed_at: string | null };
type Zoning = { available: boolean; unmapped_acres: number; zones: { jurisdiction: string; district_code: string | null; area: { acres: number } }[]; jurisdictions: { name: string | null }[]; freshness: Freshness };
type Roads = { available: boolean; state: string; distance_feet: number | null; ties: { name?: string | null; Name?: string | null; status?: string | null; Status?: string | null }[]; freshness: Freshness };
type Owner = { current_name_1: string | null; current_name_2: string | null };
let facts = $state<Section<Facts>>({ status: 'loading' });
let owner = $state<Section<Owner>>({ status: 'loading' });
let tax = $state<Section<Tax>>({ status: 'loading' });
let vacancy = $state<Section<Vacancy>>({ status: 'loading' });
let soil = $state<Section<Soil>>({ status: 'loading' });
let flood = $state<Section<FloodDetail>>({ status: 'loading' });
let zoning = $state<Section<Zoning>>({ status: 'loading' });
let roads = $state<Section<Roads>>({ status: 'loading' });
const has = (field: DetailField) => fields.includes(field);
function load<T>(id: string, path: string, assign: (state: Section<T>) => void) {
 const task = new AbortController();
 assign({ status: 'loading' });
 readMapData<T>(path, task.signal).then(data => { if (!task.signal.aborted) assign({ status: 'ready', data }); })
 .catch(() => { if (!task.signal.aborted) assign({ status: 'unavailable' }); });
 return () => task.abort();
}
$effect(() => { if (!id) return; const selected = id; return load<Facts>(id, `/api/v1/parcels/${encodeURIComponent(id)}`, state => {
 facts = state;
 if (state.status === 'ready') onlocation(selected, state.data.location?.coordinates ?? null);
 if (state.status === 'unavailable') onlocation(selected, null);
}); });
$effect(() => { if (id && has('owner_name')) return load<Owner>(id, `/api/me/parcel-owner/${encodeURIComponent(id)}`, state => owner = state); });
$effect(() => { if (id && (has('delinquent_total') || has('tax_bill_count') || has('foreclosure_count'))) return load<Tax>(id, `/api/v1/parcels/${encodeURIComponent(id)}/tax`, state => tax = state); });
$effect(() => { if (id && (has('vacancy_tier') || has('vacancy_reason'))) return load<Vacancy>(id, `/api/v1/parcels/${encodeURIComponent(id)}/vacancy`, state => vacancy = state); });
$effect(() => { if (id && (has('soil_acres') || has('soil_septic') || has('soil_dwelling_without') || has('soil_dwelling_with'))) return load<Soil>(id, `/api/v1/parcels/${encodeURIComponent(id)}/soil`, state => soil = state); });
$effect(() => { if (id && (has('flood_unknown') || has('floodway_acres') || has('flood_zones'))) return load<FloodDetail>(id, `/api/v1/parcels/${encodeURIComponent(id)}/flood`, state => flood = state); });
$effect(() => { if (id && (has('zoning_district') || has('zoning_jurisdiction') || has('zoning_unmapped'))) return load<Zoning>(id, `/api/v1/parcels/${encodeURIComponent(id)}/zoning`, state => zoning = state); });
$effect(() => { if (id && (has('road_distance') || has('road_name') || has('road_status'))) return load<Roads>(id, `/api/v1/parcels/${encodeURIComponent(id)}/roads`, state => roads = state); });
const text = (value: unknown) => value == null || value === '' ? 'Not recorded' : String(value);
const acres = (value: number) => value.toFixed(2);
const freshness = (value: Freshness) => `${value.stale ? 'Stale' : 'Stored source'} · Fetched ${text(value.source_fetched_at)}${value.refresh_failed_at ? ' · Refresh failed ' + value.refresh_failed_at : ''}${value.reasons.length ? ' · ' + value.reasons.join(', ') : ''}`;
const soilUse = (field: DetailField) => ({ soil_septic: 'conventional-septic', soil_dwelling_without: 'dwelling-without-basement', soil_dwelling_with: 'dwelling-with-basement' } as Partial<Record<DetailField, string>>)[field];
</script>
{#snippet status<T>(section: Section<T>)}{#if section.status === 'loading'}<p>Loading evidence…</p>{:else if section.status === 'unavailable'}<p>Evidence temporarily unavailable.</p>{/if}{/snippet}
<section aria-label="Parcel identity"><h2>Parcel</h2>{@render status(facts)}{#if facts.status === 'ready'}<p>{text(facts.data.parcel.parcel_number)} · {text(facts.data.parcel.address)}</p>{/if}</section>
{#if has('mapped_acres')}<section aria-label="Mapped acreage"><h2>Mapped acreage</h2>{@render status(facts)}{#if facts.status === 'ready'}<p>{text(facts.data.parcel.mapped_acres)} acres</p><details><summary>Source and limits</summary><p>{facts.data.source} · Updated {text(facts.data.parcel.updated_at)}. Mapped area is not a survey.</p></details>{/if}</section>{/if}
{#if has('owner_name')}<section aria-label="Owner name"><h2>Owner name</h2>{@render status(owner)}{#if owner.status === 'ready'}<p>{[owner.data.current_name_1, owner.data.current_name_2].filter(Boolean).join(' · ') || 'Not recorded'}</p><small>Current county parcel names, not verified contacts.</small>{/if}</section>{/if}
{#if has('entity_indicator')}<section aria-label="Entity indicator"><h2>Entity indicator</h2>{@render status(facts)}{#if facts.status === 'ready'}<p>{text(facts.data.owner_labels?.entity_name_indicator)} · Inferred county label, not verified ownership.</p>{/if}</section>{/if}
{#if has('sale_count')}<section aria-label="Stored sale count"><h2>Stored sale count</h2>{@render status(facts)}{#if facts.status === 'ready'}<p>{facts.data.sales.length} stored sales. Not a complete transaction history.</p>{/if}</section>{/if}
{#if has('delinquent_total')}<section aria-label="Reported delinquent total"><h2>Reported delinquent total</h2>{@render status(tax)}{#if tax.status === 'ready'}<p>{tax.data.reported_delinquent_total == null ? 'Not recorded' : '$' + tax.data.reported_delinquent_total}. {tax.data.note}</p>{/if}</section>{/if}
{#if has('tax_bill_count')}<section aria-label="Stored tax bill count"><h2>Stored tax bill count</h2>{@render status(tax)}{#if tax.status === 'ready'}<p>{tax.data.bills.length} stored bills. Confirm with county records.</p>{/if}</section>{/if}
{#if has('foreclosure_count')}<section aria-label="Foreclosure case count"><h2>Foreclosure case count</h2>{@render status(tax)}{#if tax.status === 'ready'}<p>{tax.data.foreclosure_cases.length} stored cases. Confirm current status.</p>{/if}</section>{/if}
{#if has('vacancy_tier')}<section aria-label="Vacancy tier"><h2>Vacancy tier</h2>{@render status(vacancy)}{#if vacancy.status === 'ready'}<p>{vacancy.data.available ? text(vacancy.data.tier) : 'No published vacancy evidence'}. Provisional classification, not occupancy verification.</p>{/if}</section>{/if}
{#if has('vacancy_reason')}<section aria-label="Vacancy reason"><h2>Vacancy reason</h2>{@render status(vacancy)}{#if vacancy.status === 'ready'}<p>{vacancy.data.available ? text(vacancy.data.reason).replaceAll('_', ' ') : 'No published vacancy evidence'}.</p>{/if}</section>{/if}
{#if has('soil_acres')}<section aria-label="Assessed soil acreage"><h2>Assessed soil acreage</h2>{@render status(soil)}{#if soil.status === 'ready'}<p>{soil.data.available ? text(soil.data.total_acres) + ' acres' : 'No published soil assessment · ' + text(soil.data.reason)}. USDA mapping, not site approval.</p>{#if soil.data.available}<small>{soil.data.freshness.stale ? 'Stale' : 'Stored source'} · {soil.data.freshness.reasons.join(', ')}</small>{/if}{/if}</section>{/if}
{#each ['soil_septic','soil_dwelling_without','soil_dwelling_with'] as field}{#if has(field as DetailField)}<section aria-label={field === 'soil_septic' ? 'Septic field rating' : field === 'soil_dwelling_without' ? 'Dwelling without basement rating' : 'Dwelling with basement rating'}><h2>{field === 'soil_septic' ? 'Septic field rating' : field === 'soil_dwelling_without' ? 'Dwelling without basement rating' : 'Dwelling with basement rating'}</h2>{@render status(soil)}{#if soil.status === 'ready'}{#if !soil.data.available}<p>No published soil assessment · {text(soil.data.reason)}</p>{:else}{@const use = soil.data.uses.find(item => item.use === soilUse(field as DetailField))}<p>{use ? use.rated.map(r => `${r.rating}: ${acres(r.area.acres)} acres`).join('; ') || 'No rated area' : 'No use-specific rating recorded'}.</p>{#if use}<details><summary>Coverage and next step</summary><p>Unrated {acres(use.unrated.acres)} · Uncovered {acres(use.uncovered.acres)} · Ambiguous {acres(use.ambiguous.acres)} acres. {use.next_step}</p></details>{/if}<small>{soil.data.freshness.stale ? 'Stale' : 'Stored source'} · {soil.data.freshness.reasons.join(', ')} · Screening only, not septic or building approval.</small>{/if}{/if}</section>{/if}{/each}
{#if has('zoning_district')}<section aria-label="Zoning district"><h2>Zoning district</h2>{@render status(zoning)}{#if zoning.status === 'ready'}<p>{zoning.data.available ? zoning.data.zones.map(z => text(z.district_code)).join(', ') || 'No district recorded' : 'No published zoning assessment'}. Check local ordinances, not permitted-use approval.</p><small>{freshness(zoning.data.freshness)}</small>{/if}</section>{/if}
{#if has('zoning_jurisdiction')}<section aria-label="Jurisdiction"><h2>Jurisdiction</h2>{@render status(zoning)}{#if zoning.status === 'ready'}<p>{zoning.data.available ? zoning.data.jurisdictions.map(j => text(j.name)).join(', ') || 'Not recorded' : 'No published zoning assessment'}</p><small>{freshness(zoning.data.freshness)}</small>{/if}</section>{/if}
{#if has('zoning_unmapped')}<section aria-label="Unmapped acreage"><h2>Unmapped acreage</h2>{@render status(zoning)}{#if zoning.status === 'ready'}<p>{zoning.data.available ? acres(zoning.data.unmapped_acres) + ' acres' : 'No published zoning assessment'}</p><small>{freshness(zoning.data.freshness)}</small>{/if}</section>{/if}
{#if has('road_distance')}<section aria-label="Mapped road distance"><h2>Mapped road distance</h2>{@render status(roads)}{#if roads.status === 'ready'}<p>{roads.data.available ? roads.data.distance_feet == null ? 'Distance not recorded' : roads.data.distance_feet.toFixed(0) + ' feet' : 'No published road assessment'}. Does not establish legal access.</p><small>{freshness(roads.data.freshness)}</small>{/if}</section>{/if}
{#if has('road_name')}<section aria-label="Nearest road name"><h2>Nearest road name</h2>{@render status(roads)}{#if roads.status === 'ready'}<p>{roads.data.available ? text(roads.data.ties[0]?.name ?? roads.data.ties[0]?.Name) : 'No published road assessment'}</p><small>{freshness(roads.data.freshness)}</small>{/if}</section>{/if}
{#if has('road_status')}<section aria-label="Road status"><h2>Road status</h2>{@render status(roads)}{#if roads.status === 'ready'}<p>{roads.data.available ? text(roads.data.ties[0]?.status ?? roads.data.ties[0]?.Status) : 'No published road assessment'}. Not legal access.</p><small>{freshness(roads.data.freshness)}</small>{/if}</section>{/if}
{#each ['flood_unknown','floodway_acres','flood_zones'] as field}{#if has(field as DetailField)}<section aria-label={field === 'flood_unknown' ? 'Unknown coverage acreage' : field === 'floodway_acres' ? 'Mapped floodway acreage' : 'Mapped flood zones'}><h2>{field === 'flood_unknown' ? 'Unknown coverage acreage' : field === 'floodway_acres' ? 'Mapped floodway acreage' : 'Mapped flood zones'}</h2>{@render status(flood)}{#if flood.status === 'ready'}{#if releaseId && flood.data.release?.id !== releaseId}<p>FEMA data changed. Refresh map to compare releases.</p>{:else if flood.data.status !== 'available'}<p>{flood.data.status === 'no_release' ? 'No FEMA release stored' : 'Parcel geometry unavailable'}.</p>{:else}<p>{field === 'flood_unknown' ? acres(flood.data.acres.unknown) + ' acres' : field === 'floodway_acres' ? acres(flood.data.acres.floodway) + ' acres' : flood.data.zones.map(z => `${z.code || 'unknown'}: ${acres(z.acres)} acres`).join('; ') || 'No mapped zone overlap'}.</p><small>FEMA archive {text(flood.data.release?.issued_at)} · Blank coverage is not proof of no flood risk. Zones may overlap.</small>{/if}{/if}</section>{/if}{/each}
<style>section { border-bottom: 1px solid var(--border); padding: 8px 0; overflow-wrap: anywhere; } h2 { font-size: 14px; font-weight: 650; } p,small { font-size: 12px; line-height: 1.5; } details { font-size: 12px; }</style>
